   274  /* get alignment arguments (inside the []) */
   275  static int get_alignment_args(char **data, int *align, int *flags, char *pad)
   276  {
   277          char *str;
   278          char *endptr;
   279          guint align_;
   280
   281          *align = 0;
   282          *flags = ALIGN_CUT|ALIGN_PAD;
   283          *pad = ' ';
   284
   285          /* '!' = don't cut, '-' = right padding */
   286          str = *data;
   287          while (*str != '\0' && *str != ']' && !i_isdigit(*str)) {
   288                  if (*str == '!')
   289                          *flags &= ~ALIGN_CUT;
   290                  else if (*str == '-')
   291                          *flags |= ALIGN_RIGHT;
   292                  else if (*str == '.')
   293                           *flags &= ~ALIGN_PAD;
   294                  str++;
   295          }
   296          if (!i_isdigit(*str))
   297                  return FALSE; /* expecting number */
   298
   299          /* get the alignment size */
   300          if (!parse_uint(str, &endptr, 10, &align_)) {
   301                  return FALSE;
   302          }
   303          str = endptr;
   304          *align = align_;
   305
   306          /* get the pad character */
   307          while (*str != '\0' && *str != ']') {
   308                  *pad = *str;
   309                  str++;
   310          }
   311
   312          if (*str++ != ']') return FALSE;
   313
   314          *data = str;
   315          return TRUE;
   316  }
