   318  /* return the aligned text */
   319  char *get_alignment(const char *text, int align, int flags, char pad)
   320  {
   321          GString *str;
   322          char *ret;
   323          int policy;
   324          unsigned int cut_bytes;
   325
   326          g_return_val_if_fail(text != NULL, NULL);
   327
   328          policy = string_policy(text);
   329
   330          str = g_string_new(text);
   331
   332          /* cut */
   333          if ((flags & ALIGN_CUT) && align > 0 && string_width(text, policy) > align) {
   334                  string_chars_for_width(text, policy, align, &cut_bytes);
   335                  g_string_truncate(str, cut_bytes);
   336          }
   337
   338          /* add pad characters */
   339          if (flags & ALIGN_PAD) {
   340                  while (string_width(str->str, policy) < align) {
   341                          if (flags & ALIGN_RIGHT)
   342                                  g_string_prepend_c(str, pad);
   343                          else
   344                                  g_string_append_c(str, pad);
   345                  }
   346          }
   347
   348          ret = str->str;
   349          g_string_free(str, FALSE);
   350          return ret;
   351  }
