   461  static void gstring_append_escaped(GString *str, const char *text, int flags)
   462  {
   463          char esc[4], *escpos;
   464
   465          escpos = esc;
   466          if (flags & PARSE_FLAG_ESCAPE_VARS)
   467                  *escpos++ = '%';
   468          if (flags & PARSE_FLAG_ESCAPE_THEME) {
   469                  *escpos++ = '{';
   470                  *escpos++ = '}';
   471          }
   472
   473          if (escpos == esc) {
   474                  g_string_append(str, text);
   475                  return;
   476          }
   477
   478          *escpos = '\0';
   479          while (*text != '\0') {
   480                  for (escpos = esc; *escpos != '\0'; escpos++) {
   481                          if (*text == *escpos) {
   482                                  g_string_append_c(str, '%');
   483                                  break;
   484                          }
   485                  }
   486                  g_string_append_c(str, *text);
   487                  text++;
   488          }
   489  }
