   491  /* parse the whole string. $ and \ chars are replaced */
   492  char *parse_special_string(const char *cmd, SERVER_REC *server, void *item,
   493                             const char *data, int *arg_used, int flags)
   494  {
   495          char code, **arglist, *ret;
   496          GString *str;
   497          int need_free, chr;
   498
   499          g_return_val_if_fail(cmd != NULL, NULL);
   500          g_return_val_if_fail(data != NULL, NULL);
   501
   502          /* create the argument list */
   503          arglist = g_strsplit(data, " ", -1);
   504
   505          if (arg_used != NULL) *arg_used = FALSE;
   506          code = 0;
   507          str = g_string_new(NULL);
   508          while (*cmd != '\0') {
   509                  if (code == '\\') {
   510                          if (*cmd == ';')
   511                                  g_string_append_c(str, ';');
   512                          else {
   513                                  chr = expand_escape(&cmd);
   514                                  g_string_append_c(str, chr != -1 ? chr : *cmd);
   515                          }
   516                          code = 0;
   517                  } else if (code == '$') {
   518                          char *ret;
   519
   520                          ret = parse_special((char **) &cmd, server, item,
   521                                              arglist, &need_free, arg_used,
   522                                              flags);
   523                          if (ret != NULL) {
   524                                  gstring_append_escaped(str, ret, flags);
   525                                  if (need_free) g_free(ret);
   526                          }
   527                          code = 0;
   528                  } else {
   529                          if (*cmd == '\\' || *cmd == '$')
   530                                  code = *cmd;
   531                          else
   532                                  g_string_append_c(str, *cmd);
   533                  }
   534
   535                  cmd++;
   536          }
   537          g_strfreev(arglist);
   538
   539          ret = str->str;
   540          g_string_free(str, FALSE);
   541          return ret;
   542  }
