   548  /* execute the commands in string - commands can be split with ';' */
   549  void eval_special_string(const char *cmd, const char *data,
   550                           SERVER_REC *server, void *item)
   551  {
   552          const char *cmdchars;
   553          char *orig, *str, *start, *ret;
   554          int arg_used, arg_used_ever;
   555          GSList *commands;
   556
   557          commands = NULL;
   558          arg_used_ever = FALSE;
   559          cmdchars = settings_get_str("cmdchars");
   560
   561          /* get a list of all the commands to run */
   562          orig = start = str = g_strdup(cmd);
   563          do {
   564                  if (is_split_char(str, start)) {
   565                          *str++ = '\0';
   566                          while (*str == ' ') str++;
   567                  } else if (*str != '\0') {
   568                          str++;
   569                          continue;
   570                  }
   571
   572                  ret = parse_special_string(start, server, item,
   573                                             data, &arg_used, 0);
   574                  if (*ret != '\0') {
   575                          if (arg_used) arg_used_ever = TRUE;
   576
   577                          if (strchr(cmdchars, *ret) == NULL) {
   578                                  /* no command char - let's put it there.. */
   579                                  char *old = ret;
   580
   581                                  ret = g_strdup_printf("%c%s", *cmdchars, old);
   582                                  g_free(old);
   583                          }
   584                          commands = g_slist_append(commands, ret);
   585                  }
   586                  start = str;
   587          } while (*start != '\0');
   588
   589          /* run the command, if no arguments were ever used, append all of them
   590             after each command */
   591          while (commands != NULL) {
   592                  ret = commands->data;
   593
   594                  if (!arg_used_ever && *data != '\0') {
   595                          char *old = ret;
   596
   597                          ret = g_strconcat(old, " ", data, NULL);
   598                          g_free(old);
   599                  }
   600
   601                  if (server != NULL)
   602                          server_ref(server);
   603                  signal_emit("send command", 3, ret, server, item);
   604
   605                  if (server != NULL && !server_unref(server)) {
   606                          /* the server was destroyed */
   607                          server = NULL;
   608                          item = NULL;
   609                  }
   610
   611                  /* FIXME: window item would need reference counting as well,
   612                     eg. "/EVAL win close;say hello" wouldn't work now.. */
   613
   614                  g_free(ret);
   615                  commands = g_slist_remove(commands, commands->data);
   616          }
   617          g_free(orig);
   618  }
