   677  /* Expand escape string, the first character in data should be the
   678     one after '\'. Returns the expanded character or -1 if error. */
   679  int expand_escape(const char **data)
   680  {
   681          char digit[4];
   682
   683          switch (**data) {
   684          case 't':
   685                  return '\t';
   686          case 'r':
   687                  return '\r';
   688          case 'n':
   689                  return '\n';
   690          case 'e':
   691                  return 27; /* ESC */
   692          case '\\':
   693                  return '\\';
   694
   695          case 'x':
   696                  /* hex digit */
   697                  if (!i_isxdigit((*data)[1]) || !i_isxdigit((*data)[2]))
   698                          return -1;
   699
   700                  digit[0] = (*data)[1];
   701                  digit[1] = (*data)[2];
   702                  digit[2] = '\0';
   703                  *data += 2;
   704                  return strtol(digit, NULL, 16);
   705          case 'c':
   706                  /* check for end of string */
   707                  if ((*data)[1] == '\0')
   708                          return 0;
   709                  /* control character (\cA = ^A) */
   710                  (*data)++;
   711                  return i_toupper(**data) - 64;
   712          case '0': case '1': case '2': case '3':
   713          case '4': case '5': case '6': case '7':
   714                  /* octal */
   715                  digit[1] = digit[2] = digit[3] = '\0';
   716                  digit[0] = (*data)[0];
   717                  if ((*data)[1] >= '0' && (*data)[1] <= '7') {
   718                          ++*data;
   719                          digit[1] = **data;
   720                          if ((*data)[1] >= '0' && (*data)[1] <= '7') {
   721                                  ++*data;
   722                                  digit[2] = **data;
   723                          }
   724                  }
   725                  return strtol(digit, NULL, 8);
   726          default:
   727                  return -1;
   728          }
   729  }
